def apply(meta: dict) -> None:
  """Overwrite the placeholder title / hook / metaphors in `meta` in place."""
  for aid, spec in STORIES.items():
    entry = meta.get(aid)
    if entry is None:
      continue
    title, hook, kit = spec[:3]
    extra = spec[3] if len(spec) > 3 else {}
    entry["title"] = title
    entry["hook"] = hook
    if entry.get("metaphors") in (None, GENERIC) or extra:
      entry["metaphors"] = {**KITS[kit], **extra}
